<?php
namespace ZinCelestial\Platform\Assets\Rollback; defined('ABSPATH')||exit;
final class SnapshotManager{const OPTION='zcp_asset_rule_snapshots';const LIMIT=10;public function create(array $rules,string $reason='manual'):string{$id=wp_generate_uuid4();$all=(array)get_option(self::OPTION,array());$all[$id]=array('id'=>$id,'created'=>time(),'user_id'=>get_current_user_id(),'reason'=>sanitize_text_field($reason),'rules'=>$rules);$all=array_slice($all,-self::LIMIT,null,true);update_option(self::OPTION,$all,false);return $id;}public function all():array{return (array)get_option(self::OPTION,array());}public function restore(string $id):bool{$all=$this->all();if(empty($all[$id]['rules']))return false;return update_option('zcp_asset_rules',(array)$all[$id]['rules'],false);}}
